const fs = require('fs');
const path = require('path');

const sessionsDir = path.join('.fastops', '.sessions');
const files = fs.readdirSync(sessionsDir).filter(f => f.endsWith('.json'));
const sessions = files.map(f => JSON.parse(fs.readFileSync(path.join(sessionsDir, f), 'utf8')));

const statusCounts = { completed: 0, failed: 0, cleaned: 0, max_turns: 0, active: 0 };
const modelStats = {};
sessions.forEach(s => {
  statusCounts[s.status] = (statusCounts[s.status] || 0) + 1;
  modelStats[s.model] = modelStats[s.model] || { total: 0, completed: 0 };
  modelStats[s.model].total++;
  if (s.status === 'completed') modelStats[s.model].completed++;
});

const total = sessions.length;
const successRate = total > 0 ? (statusCounts.completed / total * 100).toFixed(2) : 0;
console.log('Session Status Report:');
console.log(`Total Sessions: ${total}`);
console.log(`Completed: ${statusCounts.completed} (${successRate}%)`);
console.log(`Failed: ${statusCounts.failed}`);
console.log(`Cleaned: ${statusCounts.cleaned}`);
console.log(`Max Turns: ${statusCounts.max_turns}`);
console.log(`Active: ${statusCounts.active}`);
console.log('\nPer-Model Success Rates:');
Object.entries(modelStats).forEach(([model, stats]) => {
  const rate = (stats.completed / stats.total * 100).toFixed(2);
  console.log(`${model}: ${stats.completed}/${stats.total} (${rate}%)`);
});
